    category: '技术',
    definition: '该因子旨在衡量股票在过去20个交易日内的价格变动，并以此为基础判断股票的动量效应或反转效应。动量效应假定过去表现强势的股票在短期内将继续强势，反之亦然；而反转效应则认为过去表现弱势的股票可能会出现反弹，表现强势的股票可能出现回调。此因子通过观察20日区间收益率来捕捉这两种可能的市场行为。',
    formula: '因子计算公式为: c l V s e t c l V s e t − 20 close t−20 close t 公式中的参数含义: c l V s e t close t : t日（即当前交易日）的收盘价。 c l V s e t − 20 close t−20 : t-20日（即当前交易日向前推20个交易日）的收盘价。 因子解释 该因子通过计算当前收盘价 (close_t) 与 20 个交易日前的收盘价 (close_{t-20}) 的比率，来衡量股票在过去 20 个交易日内的价格变动。该比率代表了 20 日区间收益率，其数值大于1表示股票在过去20个交易日内呈现上涨趋势，数值小于1表示股票呈现下跌趋势。此因子的核心在于通过分析这一比率来判断市场主要受动量效应还是反转效应驱动。当观察到因子值与未来收益正相关时，则表明市场存在动量效应；反之，若因子值与未来收益负相关，则表明存在反转效应。 需要',
    direction: 'desc',
    application: '中，通常会结合其他因子和风险管理模型来使用该因子。 ⚠️ 因子风险警告 本量化因子仅供教育和研究目的使用。历史表现不保证未来收益。用户须独立验证并承担所有风险。 Related',
