    formula: '科技关联度计算公式: T E C H i j t = T i t ⋅ T j t ∥ T i t ∥ ∥ T j t ∥ TECH ijt = ∥T it ∥∥T jt ∥ T it ⋅T jt 科技关联加权动量因子计算公式: T E C H R E T i t = ∑ j ≠ i T E C H i j t × R E T j t ∑ j ≠ i T E C H i j t TECHRET it = ∑ j  =i TECH ijt ∑ j  =i TECH ijt ×RET jt 其中： T E C H i j t TECH ijt : 为公司i和公司j在第t期的科技关联度，取值范围在[-1, 1]，数值越高表示两公司技术关联度越高。 T i t T it : 为公司i在第t期所处的N维专利分布向量，N代表专利商标局所定义的科技大类总数。该向量的每个元素代表公司i在过去五年内获得的各类科技专利在对应科技大类中所占的比例。更具体来说，T_{it} = [t_{i1t}, t_{i2t}, ..., t_{iNt}], 其中 t_{ikt} 表示公司 i 在 t 时刻， 在第 k 类科技',
