    definition: '为主动买入成交额减去主动卖出成交额，需',
    formula: '加权最小二乘回归模型： r e t u r n i = γ u p ⋅ I i ⋅ M F i + γ d V w n ⋅ ( 1 − I i ) ⋅ M F i + 𝜖 i return i =γ up ⋅I i ⋅MF i +γ down ⋅(1−I i )⋅MF i +ϵ i 主动净买入占比: M F i = M V n e y F l V w i A m V u n t i MF i = Amount i MoneyFlow i 非对称价格冲击偏度: g a m m a b i a s = γ u p − γ d V w n V a r ( γ u p − γ d V w n ) gammabias= Var(γ up −γ down ) γ up −γ down 其中: r e t u r n i return i : 第i个5分钟K线时间段内的收益率，计算方式通常为 (收盘价 - 开盘价) / 开盘价，也可采用对数收益率 M V n e y F l V w i MoneyFlow i : 第i个5分钟K线时间段内的主动净买入金额，定义为主动买入成交额减去主动卖出成交额，需',
