    definition: '方向性动量离散指标 (DDI) 旨在衡量一段时间内价格相对于前一日的向上和向下动量分散程度。它通过比较向上和向下动量的大小，并进行平滑处理，以识别潜在的趋势反转和超买超卖区域。该指标可以辅助投资者判断市场多空力量的变化，以及趋势的潜在强弱。DDI指标的核心思想是关注价格波动背后的动能变化，并以此作为交易决策的依据。',
    formula: '向上动量 (DMZ) = D M Z = { 0 , if H I K H t + L O W t ≤ H I K H t − 1 + L O W t − 1 max ⁡ ( ∣ H I K H t − H I K H t − 1 ∣ , ∣ L O W t − L O W t − 1 ∣ ) , otherwise DMZ={ 0, max(∣HIGH t −HIGH t−1 ∣,∣LOW t −LOW t−1 ∣), if HIGH t +LOW t ≤HIGH t−1 +LOW t−1 otherwise 向下动量 (DMF) = D M F = { 0 , if H I K H t + L O W t > H I K H t − 1 + L O W t − 1 max ⁡ ( ∣ H I K H t − H I K H t − 1 ∣ , ∣ L O W t − L O W t − 1 ∣ ) , otherwise DMF={ 0, max(∣HIGH t −HIGH t−1 ∣,∣LOW t −LOW t−1 ∣), if HIGH t +LOW t >HIGH t−1 +LOW t−1 otherwise 正向动量指数 (DIZ) = D I Z t = ∑ i = t − N + 1 t D M Z i ∑ i = t − N + 1 t D M Z i + ∑ i = t − N + 1 t D M F i × 100 DIZ t = ∑ i=t−N+1 t DMZ i +∑ i=t−N+1 t DMF i ∑ i=t−N+1 t DMZ i ×100 负向动量指数 (DIF) = D I F t = ∑ i = t − N + 1 t D M F i ∑ i = t − N + 1 t D M Z i + ∑ i = t − N + 1 t D M F i × 100 DIF t = ∑ i=t−N+1 t DMZ i +∑ i=t−N+1 t DMF i ∑ i=t−N+1 t DMF i ×100',
