    definition: '该因子通过计算价格序列一阶差分的正向和负向自相关性，并进行标准化处理，从而衡量股票价格变动的持续性。该因子倾向于捕捉价格变动方向的反转特征，即不希望股价连续出现相同方向的大幅波动。因子值越低的股票，表示其价格变动方向更倾向于反转，可能预示着未来的收益机会。',
    formula: 'CDPDP: C D P D P = C V r r P V s − m e a n ( C V r r P V s ) s t d ( C V r r P V s ) + C V r r N e g − m e a n ( C V r r N e g ) s t d ( C V r r N e g ) CDPDP= std(CorrPos) CorrPos−mean(CorrPos) + std(CorrNeg) CorrNeg−mean(CorrNeg) 其中: Δ P t ΔP t : 第t个时间点的价格一阶差分，计算公式为 \Delta P_t = P_t - P_{t-1}，其中 P_t 为t时刻的价格。 C V r r P V s CorrPos : 正向价格差分自相关性，表示在价格差分大于零的情况下（即 \Delta P_t > 0 ），取 \Delta P_t 和 \Delta P_{t+1} 构成的序列的20日相关系数的平均值。该值衡量了价格上涨的持续性。 C V r r N e g CorrNeg : 负向价格差分自相关性，表示在价格差分小于零的情况下（即 \Delta P_t < 0），取 \Delta P_t 和 \Delta P_{t+1}构成的序列的20日相关系数的平均值。该值衡量了价格下跌的持续性。 m e a n ( ) mean() : 表示求取平均值操作，用于计算正向和负向自相关性的均值。 s t d ( ) std() : 表示求取标准差操作，用于计算正向和负向自相关性的标准差，进行标准化处理。 因子解释 该因子逻辑基于价格的均值回归特性，并利用双序列差分的方式增强其捕捉反转信号的能力。当股票价格连续出现同',
