    definition: '为单笔成交金额大于100万元的交易。该序列记录了每日超大单的净流入金额（买入金额减去卖出金额）。 S t S t : 过去20个交易日小单净流入资金的时间序列。小单定义为单笔成交金额小于4万元的交易。该序列记录了每日小单的净流入金额（买入金额减去卖出金额）。 rho R a n k ( X , Y ) ρ Rank (X,Y) :',
    formula: '资金流同步秩相关性公式: rho R a n k ( E L t , S t ) ρ Rank (EL t ,S t ) 其中: E L t EL t : 过去20个交易日超大单净流入资金的时间序列。超大单定义为单笔成交金额大于100万元的交易。该序列记录了每日超大单的净流入金额（买入金额减去卖出金额）。 S t S t : 过去20个交易日小单净流入资金的时间序列。小单定义为单笔成交金额小于4万元的交易。该序列记录了每日小单的净流入金额（买入金额减去卖出金额）。 rho R a n k ( X , Y ) ρ Rank (X,Y) : 计算时间序列X和Y的Spearman秩相关系数。秩相关系数衡量两个变量排序的一致性，取值范围在-1到1之间。正值表示两个变量排序趋势相同，负值表示排序趋势相反，0表示没有线性相关性。 因子解释 该因子通过计算超大单和小单资金净流入序列的Spearman秩相关性，来衡量两者在一段时间内的同步程度。正的秩相关系数可能表明市场参与者（尤其是散户和机构）在情绪上趋于一致，例如，当市场整体看好时，两者都可能呈现净流入；负的秩相关系数可能表明两者在行为上存在分歧，例如，当机构抛售时，散户可能选择抄底。然而，需要',
