    name: '分析师覆盖度',
    abbr: 'AC',
    category: '情绪',
    definition: '衡量特定时间段内（例如，过去三个月）对某上市公司发布研究报告的卖方分析师（或机构）的数量。该指标旨在反映市场对该公司的关注程度和信息透明度。',
    formula: '分析师覆盖度指标通过统计一段时间内关注并发布研究报告的分析师数量来量化市场对该公司的关注度。该指标越高，代表市场对该公司的信息关注度越高。 因子解释 分析师覆盖度可以被视为衡量市场对公司信息确定性的一种指标。高覆盖度通常意味着公司信息更加透明，市场对公司的基本面有更充分的了解，这可能降低公司被高估的可能性。此外，分析师覆盖度也可能反映了市场的交易活跃度，高覆盖度可能导致短期内市场过度关注，从而产生短期过热的风险，并可能在未来出现回调。 因此，该因子既可以被视为一种价值信号，也可以被视为一种动量或反转信号，具体如何解读取决于其他市场因素和模型设定。该因子也可以被视作一个衡量信息披露程度的指标，越被关注的公司信息透明度越高。 ⚠️ 因子风险警告 本量化因子仅供教育和研究目的使用。历史表现不保证未来收益。用户须独立验证并承担所有风险。 参考资料 以下学术和行业资源为这个交易因子提供了额外的背景和验证。 Charles M.C. Lee, Eric C. So. (2016). Uncovering expected returns: Information in analyst coverage proxies. Journal of Financial Economics 124(2), 331-348 朱剑涛. (2017). 分析师研报的数据特征与 alpha. 东方证券 Related',
