    category: '情绪',
    definition: '主动买入冲击因子衡量了高频交易数据中，主动买入交易量对股票价格收益率的边际影响。该因子旨在捕捉市场微观结构中，买方力量对股价的推动效应。由于投资者普遍存在亏损厌恶心理，卖方力量对股价的冲击往往更为显著，因此主动买入冲击因子的预测能力可能弱于主动卖出冲击因子。本因子关注主动买入行为对价格形成的贡献，反映了买方力量在流动性冲击层面的强度。',
    formula: '使用线性回归模型估计主动买入冲击系数。 r i , t = α + β 1 ∗ S i , t + β 2 ∗ B i , t + 𝜖 i , t r i,t =α+β 1 ∗S i,t +β 2 ∗B i,t +ϵ i,t 其中: β 1 β 1 : 为卖出冲击系数，表示在t时间区间内，单位主动卖出交易量对股票i收益率的边际影响。该系数反映了卖方力量对股价的下行压力。 β 2 β 2 : 为买入冲击系数，表示在t时间区间内，单位主动买入交易量对股票i收益率的边际影响。该系数是本因子的核心，反映了买方力量对股价的上行推动。 S i , t S i,t : 为股票i在t时间区间内的主动卖出交易量，通常以成交金额或成交笔数衡量。需要',
