    name: '一致预期收益率 (Consensus Target Price Return)',
    abbr: 'C_ER',
    category: '情绪',
    definition: '一致预期收益率反映了市场分析师对股票未来潜在收益的平均预期。该指标通过汇总多家机构给出的目标价格，并与当前股价进行比较，衡量市场对该股票的整体乐观程度。一致预期收益率越高，表明分析师群体对该股票未来表现的看好程度越高，反之亦然。该因子可作为衡量市场情绪和基本面预期的综合指标。',
    formula: '一致预期收益率公式： R c V n s e n s u s = ∑ i = 1 N P i e − P P N = 1 N ∑ i = 1 N P i e P − 1 R consensus = N ∑ i=1 N P P i e −P = N 1 i=1 ∑ N P P i e −1 其中： P i e P i e : 第i家机构发布的股票目标价格，反映该机构对股票未来价格的预期。 P P : 月末计算因子时的股票收盘价，作为当前股价的基准。 N N : 发布分析师预期目标价格的机构数量，代表参与预测的分析师数量。 R c V n s e n s u s R consensus : 一致预期收益率，表示所有分析师预期目标价格相对于当前价格的平均预期收益率。 因子解释 该因子计算了所有分析师目标价相对于当前股价的平均收益率，其绝对值越大表示市场预期该股票未来价格波动幅度越大。一致预期收益率的符号（正负）表示市场对股票未来收益的预期',
