    definition: '该因子衡量陆股通资金的净流入强度，通过计算当日陆股通净流入金额与当日陆股通买入和卖出成交总额的比值，反映外资通过陆股通渠道流入A股市场的资金活跃程度。该比率越高，表示外资流入意愿越强，反之则表明外资流出意愿较强。该因子可用于辅助判断市场情绪和外资流动性趋势。',
    formula: '陆股通净流入强度比率: 陆股通净流入强度比率 = 陆股通净流入金额 陆股通买入成交额 + 陆股通卖出成交额 陆股通净流入强度比率= 陆股通买入成交额+陆股通卖出成交额 陆股通净流入金额 公式中各项参数的含义如下： 陆股通净流入金额 陆股通净流入金额 : 指当日通过沪股通和深股通流入A股市场的资金总额，减去流出A股市场的资金总额。正值表示净流入，负值表示净流出。该值反映了外资当日对A股的总体投资意愿和资金流向。 陆股通买入成交额 陆股通买入成交额 : 指当日通过沪股通和深股通买入A股股票的总成交金额。该值反映了外资当日的买入活跃度和对A股的买盘力度。 陆股通卖出成交额 陆股通卖出成交额 : 指当日通过沪股通和深股通卖出A股股票的总成交金额。该值反映了外资当日的卖出活跃度和对A股的卖盘压力。 因子解释 陆股通净流入强度比率正负值代表了外资的整体流入和流出',
