    formula: '盈余公告日次日开盘跳空幅度: O p e n t + 1 C l V s e t − 1 Close t Open t+1 −1 其中： O p e n t + 1 Open t+1 : 表示盈余公告发布日（t日）的下一个交易日（t+1日）的开盘价格。 C l V s e t Close t : 表示盈余公告发布日（t日）的收盘价格。 因子解释 盈余公告日次日开盘跳空幅度反映了市场对盈余公告的即时反应强度和',
