    name: '投资者关注度占比因子',
    abbr: 'CSR',
    category: '情绪',
    definition: '该因子衡量投资者对特定股票的关注程度，通过计算自选股池中该股票出现的频率来表征。自选股池被认为是投资者主动关注和偏好的体现，而非被动的信息接收。该因子反映了市场参与者对个股的内生兴趣和选择，与股票未来收益之间可能存在负相关关系，即高关注度可能预示股价回调。',
    formula: '该因子计算公式较为简单，本质上是对自选股池进行统计，其隐含的公式可以理解为： i i : 代表特定的目标股票。 N ( i ) N(i) : 在所有投资者自选股池中，股票 i 被选中的总次数（或投资者人数）。 j j : 代表所有被选入自选股池的股票，包括目标股票 i。 ∑ N ( j ) ∑N(j) : 在所有投资者自选股池中，所有股票被选中的总次数（或投资者人数），可以认为是所有自选股池的总规模。 因子解释 投资者关注度占比因子旨在量化投资者对特定股票的关注程度，其核心假设是：被更多投资者加入自选股池的股票，更能反映市场的整体偏好。由于自选股池代表了投资者主动的筛选和偏好，而非被动的信息接收，因此其包含的信息具有较高的价值。高关注度占比可能意味着市场对该股票的预期较高，但也可能导致股价泡沫，因此与股票未来收益之间往往呈现负相关性。该因子可用于捕捉市场情绪，并在量化交易策略中作为反向指标使用，即高关注度占比时，应谨慎对待该股票。 ⚠️ 因子风险警告 本量化因子仅供教育和研究目的使用。历史表现不保证未来收益。用户须独立验证并承担所有风险。 参考资料 以下学术和行业资源为这个交易因子提供了额外的背景和验证。 魏建榕,胡亮勇. (2022). 自选股与点击量:投资者关注度的选股能力. 开源证券 Related',
