    id: 'weighted-earnings-adjustment',
    name: '分析师预测加权盈余修正幅度',
    abbr: 'W_EA',
    category: '情绪',
    definition: '为：本次预测净利润相比于同一分析师在1个月前6个月内的同报告期最新一次预测净利润的百分比变化。 3. 采用Accwt2方法对过去3个月内每家分析机构的最后一次预测净利润调整幅度进行加权，得到加权盈余修正幅度。 说明: 传统的盈余修正度量方法通常使用一致预期净利润的变化率，而本因子采用加权方式，考虑了分析师预测的异质性，能够更准确地捕捉市场对盈利预期的变动。 A c c w t 2 Accwt2 : Accwt2 加权方法是一种基于分析师预测水平的加权方式。该加权方法可能考虑了分析师的预测精度、历史预测偏差以及覆盖率等因素，以提高加权平均的可靠性。具体的Accwt2加权方法细节需要参考相关文档或研究。 该因子旨在捕捉分析师对公司盈利预测的修正行为，并采用加权方式整合不同分析师的观点。传统的盈余修正度量通常直接采用一致预期净利润的变化率，而该因子更进一步，通过考虑分析师个体预测的差异性，并根据分析师的预测质量进行加权，从而更精确地反映市场对公司盈利预期变化的真实看法。高修正幅度通常预示着市场对公司盈利前景的显著看法转变，可能对股票价格产生影响。 ⚠️ 因子风险警告 本量化因子仅供教育和研究目的使用。历史表现不保证未来收益。用户须独立验证并承担所有风险。 参考资料 以下学术和行业资源为这个交易因子提供了额外的背景和验证。 朱剑涛. (2017). 分析师研报的数据特征与alpha. 东方证券 Related',
    formula: '1. 计算每家分析机构在过去3个月内最后一次发布的净利润预测调整幅度。 2. 单次预测调整幅度定义为：本次预测净利润相比于同一分析师在1个月前6个月内的同报告期最新一次预测净利润的百分比变化。 3. 采用Accwt2方法对过去3个月内每家分析机构的最后一次预测净利润调整幅度进行加权，得到加权盈余修正幅度。 说明: 传统的盈余修正度量方法通常使用一致预期净利润的变化率，而本因子采用加权方式，考虑了分析师预测的异质性，能够更准确地捕捉市场对盈利预期的变动。 A c c w t 2 Accwt2 : Accwt2 加权方法是一种基于分析师预测水平的加权方式。该加权方法可能考虑了分析师的预测精度、历史预测偏差以及覆盖率等因素，以提高加权平均的可靠性。具体的Accwt2加权方法细节需要参考相关文档或研究。 因子解释 该因子旨在捕捉分析师对公司盈利预测的修正行为，并采用加权方式整合不同分析师的观点。传统的盈余修正度量通常直接采用一致预期净利润的变化率，而该因子更进一步，通过考虑分析师个体预测的差异性，并根据分析师的预测质量进行加权，从而更精确地反映市场对公司盈利预期变化的真实看法。高修正幅度通常预示着市场对公司盈利前景的显著看法转变，可能对股票价格产生影响。 ⚠️ 因子风险警告 本量化因子仅供教育和研究目的使用。历史表现不保证未来收益。用户须独立验证并承担所有风险。 参考资料 以下学术和行业资源为这个交易因子提供了额外的背景和验证。 朱剑涛. (2017). 分析师研报的数据特征与alpha. 东方证券 Related',
