    definition: '可能存在差异，需要根据实际情况进行校准。 总股本 总股本 : 指报告期末，公司已发行的全部股份总数。总股本通常由公司定期报告或交易所公开信息披露。需要',
    formula: '机构投资者持股比例: 机构投资者持股数量 总股本 总股本 机构投资者持股数量 公式中，分子代表报告期末机构投资者所持有的公司股份数量，分母代表报告期末公司已发行的全部股份数量。 机构投资者持股数量 机构投资者持股数量 : 指报告期末，机构投资者（包括但不限于基金、保险、券商、QFII等）直接或间接持有的公司股份总数。该数据通常来源于公司定期报告（如年报、半年报、季报）中披露的机构股东持股信息，或交易所公开的持股数据。需要',
