    definition: '该因子衡量在年度区间内，剔除股票价格波动影响后，由股权发行所导致的市值年度变动情况。该因子反映了公司通过发行新股融资的活跃程度，与股票未来收益通常呈现负相关关系，即存在“综合股权发行效应”。除年度区间外，该因子也可应用于其他时间区间，例如单季度或过去五年等，以衡量不同时间尺度下的股权发行活动对公司市值的贡献。',
    formula: '年度股权发行调整市值增长率 = ln(当前总市值 / 上年同期总市值) - ln(1 + 相同时间区间内的累计收益率) ln ⁡ ( C u r r e n t M a r k e t C a p L a g g e d M a r k e t C a p ) − ln ⁡ ( 1 + C u m u l a t i v e R e t u r n ) ln( LaggedMarketCap CurrentMarketCap )−ln(1+CumulativeReturn) 该公式计算年度股权发行调整的市值增长率，通过对数化的市值比率减去对数化的累计收益率，旨在剔除股价波动对市值变化的影响，从而更准确地反映股权发行对市值的影响。 C u r r e n t M a r k e t C a p CurrentMarketCap : 当前最新总市值。指在计算该因子时，公司在当前时间点的总市值。总市值等于公司发行的所有股票的市场价格乘以其发行量。 L a g g e d M a r k e t C a p LaggedMarketCap : 上年同期的总市值。指公司在当前时间点前一年的同一时间点的总市值。用于计算市值的年度变化。 C u m u l a t i v e R e t u r n CumulativeReturn : 相同时间区间内的累计收益率。 指在当前时间点和上年同期之间，股票价格的累计收益率。用于剔除股价波动对市值的影响，从而更精确地计算股权发行对市值的贡献。累计收益率可通过计算价格变动百分比或者通过持有期间的收益率来获取。 因子解释 该因子通过计算年度市值增长率与同期股票累计收益率之间的差异，衡量公司在年度内由股权发行所导致的市值变动。其核心思想是，当公司进行股权融资时，会稀释现有股东的权益，并可能被市场解读为公司可能面临资金需求压力或前景不佳的信号，从而导致未来收益可能受到负面影响。因此，该因子与未来股票收益通常呈现负相关关系，体现了“综合股权发行效应”。该因子适用于不同时间区间，以捕捉不同时间尺度下股权发行对公司市值的影响。高数值通常意味着公司在该年度发行了较多的股票，可能预示着未来股票收益率的降低。 ⚠️ 因子风险警告 本量化因子仅供教育和研究目的使用。历史表现不保证未来收益。用户须独立验证并承担所有风险。 参考资料 以下学术和行业资源为这个交易因子提供了额外的背景和验证。 Daniel, Kent D., and Sheridan Titman. (2006). Market reactions to tangible and intangible information. Journal of Finance Related',
