    tips: ['分母为负时比率含义需谨慎解读', '该指标侧重于现金流结构而非绝对量', '关注比率的趋势变化比单期值更有价值', '需结合投资和筹资活动现金流综合分析'],
    source: 'factors.directory',
    sourceUrl: 'https://factors.directory/zh/factors/basic-surface/proportion-of-net-cash-flow-from-operations',
