    id: 'independent-claim-count',
    name: '五年滚动平均独立权利要求项数',
    abbr: 'ICC',
    category: '基本面',
    definition: '该因子衡量的是过去五年内，企业新获批的有效发明专利中，平均每项专利所包含的独立权利要求项的数量。该指标反映了企业专利组合的技术复杂度和保护范围，是衡量专利质量的重要维度。',
    formula: '因子解释 独立权利要求项是指不依赖于其他权利要求来确定其保护范围和技术特征的完整权利要求。 独立权利要求项的数量越多，通常意味着该项专利覆盖的技术范围更广，创新程度更高，商业价值也可能更大。该因子旨在评估企业专利的技术深度和广度。 滚动平均计算方式可以平滑短期波动，更好地反映企业长期创新能力。 ⚠️ 因子风险警告 本量化因子仅供教育和研究目的使用。历史表现不保证未来收益。用户须独立验证并承担所有风险。 参考资料 以下学术和行业资源为这个交易因子提供了额外的背景和验证。 郑兆磊. (2022). 专利研究系列四:专利全解析. 兴业证券 Related',
